import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { IProductCategoryModel, ProductCategoryModel } from '../../../../../data/model/product/ProductCategoryModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { ProductService } from 'src/app/data/service/product/product.service';

@Component({
  selector: 'app-edit-product-category',
  templateUrl: './edit-product-category.component.html',
  styleUrls: ['./edit-product-category.component.scss']
})
export class EditProductCategoryComponent implements OnInit {

  form: FormGroup;
  selectedCategoryModel: IProductCategoryModel;
  categorySelected = false;
  selectedCategory = 'tuning';
  selectedCategoryId = '1';

  constructor(
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController,
    private productService: ProductService
  ) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(200)]],
      url: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(200)]]
    });
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onUpdate(): void {

    if (this.form.valid) {

      SharedIonic.loading(this.loadingController);

      this.productService.AddOrUpdateProductCategory(
        new ProductCategoryModel(
          this.selectedCategoryModel.productCategoryId,
          this.form.value.title,
          this.form.value.url,
          +this.selectedCategoryId
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            SharedIonic.successToast(this.toastController);

            this.productService.GetAllProductsCategory().subscribe(
              res => {
                if (res.status === GResponse.SuccessStatus) {
                  GResponse.ProductCategory = res.data;
                }
              }
            );
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onCancel(): void {

    this.categorySelected = false;
  }

  onSelectItem(model: IProductCategoryModel) {

    this.selectedCategoryId = model.parentId.toString();

    this.selectedCategoryModel = model;

    this.form.setValue({
      title: this.selectedCategoryModel.title,
      url: this.selectedCategoryModel.urlTitle
    });
    this.categorySelected = true;
  }
}
